def compute(vars):
    current_year_revenue = vars["Current Year Revenue"]
    previous_year_revenue = vars["Previous Year Revenue"]

    if previous_year_revenue == 0:
        return None

    growth_rate = (current_year_revenue - previous_year_revenue) / previous_year_revenue

    return {
        "value": growth_rate,
        "trace": {
            "Current Year Revenue": current_year_revenue,
            "Previous Year Revenue": previous_year_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
